def resolve(path, cwd, links):
    # Normalize the path to absolute
    if path.startswith('/'):
        current = '/'
        components = [c for c in path.split('/') if c and c != '.']
    else:
        current = cwd
        components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append the component
            if current == '/':
                next_path = '/' + component
            else:
                next_path = current + '/' + component

            # Check if this path is a symlink
            if next_path in links:
                link_count += 1
                if link_count > 8:
                    return None

                # Resolve the link target
                target = links[next_path]

                # Split target into components
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative symlink target (relative to the directory containing the link)
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Insert the target components into our component list
                remaining = components[i + 1:]
                components = target_components + remaining
                i = 0
            else:
                # Not a symlink, just move to this path
                current = next_path

        i += 1

    # Return the result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

